import {INTRO,STAGES,RECORDINGS} from './story.js';
import {SAVE_KEY,freshState,restoreState,submitSolo,currentStage,advance,revealHint,hintTotal,escapeHtml as esc} from './engine.js';
import {teamConfigured,loadTeam,saveTeam,clearTeam,teamRequest} from './team.js';

const app=document.querySelector('#app'),sheet=document.querySelector('#sheet');
let storageOK=true;
let session=loadTeam(),teamData=null,connection='connecting',pollTimer=null,pollDelay=5000;
const activeSaveKey=()=>session?`${SAVE_KEY}:team:${session.code}`:SAVE_KEY;
let state;try{state=restoreState(localStorage.getItem(activeSaveKey()));}catch{state=freshState();storageOK=false;}
let screen='home',tab='play',introMode=false,puzzleOpen=false,pin='',bank='',direction='',pathChoice='',verifyOpen=false,busy=false;
let sound=false;try{sound=localStorage.getItem('yangjae:sound')==='true';}catch{}
let audioContext=null,speakingId=null,toastTimer=null;
const paths={arrow:'M7 17 17 7M7 7h10v10',back:'m15 18-6-6 6-6',lock:'M7 10V7a5 5 0 0 1 10 0v3M5 10h14v11H5zM12 14v3',unlock:'M7 10V7a5 5 0 0 1 9-3M5 10h14v11H5zM12 14v3',play:'m8 5 12 7-12 7z',pause:'M8 5v14M16 5v14',sound:'m11 5-6 4H2v6h3l6 4zM15 8a6 6 0 0 1 0 8M18 5a10 10 0 0 1 0 14',mute:'m11 5-6 4H2v6h3l6 4zM16 9l6 6M22 9l-6 6',folder:'M3 7V4h6l3 3h9v13H3z',message:'M3 3h18v14H8l-5 4zM7 7h10M7 11h7',pin:'M19 9c0 5-7 12-7 12S5 14 5 9a7 7 0 0 1 14 0zM12 7v4M10 9h4',check:'m5 12 4 4L19 6',x:'m6 6 12 12M18 6 6 18',help:'M9 8a3 3 0 1 1 4 3c-1 .5-1 1-1 3M12 18h.01',settings:'M4 7h16M4 17h16M8 4v6M16 14v6',users:'M8 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8zM1 21v-3a7 7 0 0 1 14 0v3M16 4a4 4 0 0 1 0 8M19 16a6 6 0 0 1 3 5',copy:'M9 9h12v12H9zM15 5V3H3v12h2',eye:'M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12zM15 12a3 3 0 1 1-6 0 3 3 0 0 1 6 0',clock:'M12 8v5l3 2M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0z',info:'M12 10v7M12 7h.01M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0z'};
function icon(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.info}"/></svg>`;}
function button(action,label,cls='secondary',extra=''){return `<button class="${cls}" data-action="${action}" ${extra}>${label}</button>`;}
function save(){try{localStorage.setItem(activeSaveKey(),JSON.stringify(state));}catch{storageOK=false;}}
function toast(message){clearTimeout(toastTimer);const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),4400);}
function stopVoice(){if('speechSynthesis'in window)window.speechSynthesis.cancel();speakingId=null;document.querySelectorAll('[data-action="speak"]').forEach(el=>{el.classList.remove('playing');el.setAttribute('aria-pressed','false');});}
function tone(unlock=false){if(!sound)return;try{audioContext??=new (window.AudioContext||window.webkitAudioContext)();audioContext.resume();[0,...(unlock?[.14,.28]:[])].forEach((offset,i)=>{const o=audioContext.createOscillator(),g=audioContext.createGain(),t=audioContext.currentTime+offset;o.type='sine';o.frequency.value=unlock?[392,494,587][i]:420;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.035,t+.01);g.gain.exponentialRampToValueAtTime(.001,t+.2);o.connect(g);g.connect(audioContext.destination);o.start(t);o.stop(t+.21);});}catch{}}
function effectButton(){return button('sound',icon(sound?'sound':'mute'),'icon-button',`aria-label="효과음 ${sound?'끄기':'켜기'}" aria-pressed="${sound}"`);}
function home(){
  return `<main class="title-screen"><div class="cover-photo" role="img" aria-label="양재천의 물길과 다리 풍경"></div><div class="cover-shade"></div><header class="brand"><span class="brand-name">${icon('folder')} 기록 산책</span><div class="header-actions"><span class="case-label">CASE 001 · 양재천</span>${effectButton()}${button('about',icon('info'),'icon-button','aria-label="체험 안내와 사진 출처"')}</div></header><div class="title-body"><p class="eyebrow"><span class="tiny-line"></span> 양재천 미스터리 · 첫 번째 사건</p><h1>지워진<br><em>11</em>분<span class="title-dot">.</span></h1><p class="tagline">당신을 안내하는 사람은,<br>당신이 무엇을 발견할지 이미 알고 있다.</p><div class="title-meta"><span>${icon('lock')} 5개의 잠긴 기록</span><span>${icon('clock')} 나만의 속도로</span></div>${button('start',`${state.started?'이어서 기록 열기':'기록 열기'} ${icon('arrow')}`,'primary')}${button('team-menu',`${icon('users')} ${session?'우리 팀으로 돌아가기':'함께 체험하기'}`,'text-button team-entry')}<div class="trial-note"><span>사전 체험판</span><p>지금 있는 곳에서 플레이하세요.<br>현장 이동 없이, 모든 단서가 화면에 제공됩니다.</p></div></div><aside class="cover-annotation"><span>ARCHIVE / YANGJAECHEON</span><strong>19:42 <i>—</i> 19:53</strong><span>누락된 기록 · 11분</span></aside><footer class="title-footer"><span>사진 속 양재천은 2016년의 기록입니다.</span><button data-action="about">체험 안내 · 출처 ↗</button></footer></main>`;
}
function sideRail(){const idx=currentStage(state);return `<aside class="case-rail"><button class="rail-brand" data-action="home">${icon('folder')} 기록 산책</button><div class="rail-art"></div><p class="eyebrow">CASE 001</p><h2>지워진 <em>11</em>분.</h2><p class="rail-caption">서로 맞지 않는 기록 사이에서<br>그날의 진실을 찾아보세요.</p><ol class="chapter-list">${STAGES.map((s,i)=>`<li class="${state.solved>i?'complete':i===idx?'current':''}"><span class="chapter-marker">${state.solved>i?icon('check'):s.number}</span><div><span>${state.solved>i?'복원 완료':i===idx?'현재 기록':'잠긴 기록'}</span><strong>${state.solved>=i?s.name:'기록 '+s.number}</strong></div></li>`).join('')}</ol><div class="rail-foot">${icon('pin')} 사전 체험 · 실제 이동 없음</div></aside>`;}
function nav(){return `<nav class="bottom-nav" aria-label="게임 메뉴">${[['play','lock','진행'],['evidence','folder','증거함'],['log','message','대화 기록']].map(([t,i,l])=>button('tab',`${icon(i)}<span>${l}${t==='evidence'?` <b>${Math.min(state.solved,4)}</b>`:''}</span>`,tab===t?'nav-item active':'nav-item',`data-tab="${t}" ${tab===t?'aria-current="page"':''}`)).join('')}</nav>`;}
function shell(content){return `<div class="game-shell">${sideRail()}<div class="game-main"><header class="game-header"><div class="header-left">${button('home',icon('back'),'icon-button','aria-label="첫 화면으로 돌아가기"')}<div><strong>지워진 11분</strong><span>${session?`팀 ${esc(session.code)}`:'혼자 체험 중'}</span></div></div><div class="header-actions">${session?button('team-menu',icon('users'),'icon-button','aria-label="우리 팀 정보"'):''}${effectButton()}${button('settings',icon('settings'),'icon-button','aria-label="체험 설정"')}</div></header><div class="progress-line" role="progressbar" aria-label="복원한 기록" aria-valuenow="${state.solved}" aria-valuemin="0" aria-valuemax="5"><span style="width:${state.solved*20}%"></span></div>${(!navigator.onLine)?`<p class="status-banner">${session?'인터넷 연결이 끊겼습니다. 연결되면 팀 진행을 다시 불러옵니다.':'오프라인 체험 중 · 진행은 이 기기에 저장됩니다.'}</p>`:''}${!storageOK?'<p class="status-banner">브라우저 저장 공간을 사용할 수 없어, 창을 닫으면 진행이 사라질 수 있어요.</p>':''}${session&&connection==='error'?'<p class="status-banner">팀 연결을 다시 시도하고 있습니다. '+button('sync','지금 다시 연결','inline-button')+'</p>':''}<main class="play-content" id="play-content">${content}</main>${nav()}</div><aside class="desk-note"><span class="eyebrow">THE MISSING RECORD</span><p>익숙한 풍경도<br>다시 보면<br>다른 이야기가 된다.</p><div class="desk-lines"></div><span>19:42 — 19:53</span></aside></div>`;}
function message(m,i,animate=false){const sys=m.from==='system';return sys?`<div class="system-message ${animate?'arrive':''}">${esc(m.text).replaceAll('\n','<br>')}</div>`:`<article class="chat-message ${animate?'arrive':''}"><div class="avatar ${m.from.includes('윤서')?'yun':''}" aria-hidden="true">${m.from.includes('윤서')?'윤':m.from==='도현'?'도':'기'}</div><div><div class="message-from">${esc(m.from)}<span>기록 ${String(i+1).padStart(2,'0')}</span></div><div class="bubble">${esc(m.text).replaceAll('\n','<br>')}</div></div></article>`;}
function storyView(){const s=STAGES[currentStage(state)],messages=introMode?INTRO:s.messages,key=introMode?'intro':s.id,count=Math.max(1,state.reads[key]||1);return `<div class="section-kicker">${introMode?'초대 메시지':`기록 ${s.number} / 05`}<span>사전 체험</span></div><h2 class="page-title">${introMode?'누군가의 초대':s.name}</h2><p class="subtitle">${introMode?'평범한 산책이 끝난 자리에서, 이야기가 시작된다.':s.subtitle}</p><div class="messages" aria-live="polite">${messages.slice(0,count).map((m,i)=>message(m,i,i===count-1)).join('')}</div><div class="story-next">${count<messages.length?button('read-next',`계속 읽기 <span>${count} / ${messages.length}</span>`,'primary'):button(introMode?'intro-done':'puzzle',`${introMode?'첫 번째 기록으로':'단서 확인하기'} ${icon('arrow')}`,'primary')}</div><p class="footnote">${introMode?'등장인물과 사건은 모두 허구입니다.':'대화는 아래 ‘대화 기록’에서 다시 볼 수 있습니다.'}</p>`;}
function photoPuzzle(){return `<div class="clue-head"><span>단서 01 · 윤서의 사진</span>${button('original',`${icon('eye')} 원본 크게 보기`,'inline-button')}</div><figure class="reference-photo"><img src="./assets/yangjaecheon.jpg" alt="비교할 원본 사진: 왼쪽 나뭇가지, 중앙 교량, 오른쪽 건물과 물길"><figcaption>전체 사진 · 왼쪽에서 오른쪽으로</figcaption></figure><div class="photo-strips">${[{num:4,pos:2},{num:2,pos:3},{num:3,pos:0},{num:1,pos:1}].map(p=>`<button class="photo-strip" data-action="fragment" data-num="${p.num}" data-pos="${p.pos}" aria-label="숫자 ${p.num} 사진 조각 확대"><span class="strip-image" style="background-position:${p.pos/3*100}% center"></span><span class="strip-number">${p.num}</span></button>`).join('')}</div><p class="micro">사진을 왼쪽부터 복원한 뒤, 각 조각의 숫자를 읽으세요.</p>`;}
function bankPuzzle(){return `<div class="notebook"><span class="note-label">윤서의 촬영 메모</span><p>“다리 쪽을 바라봤다.<br>물 건너 <strong>계단이 오른쪽</strong>에 있었다.”</p></div><div class="viewpoint-map"><div class="map-label">사전 체험용 관찰도 · 실제 길 안내가 아닙니다</div><svg viewBox="0 0 480 300" role="img" aria-label="가상 지도. 위쪽에 다리, 중앙에 물길, 왼쪽 A 강변, 오른쪽 B 강변과 계단. 두 강변에서 위를 보면 A에서만 계단이 오른쪽에 있습니다."><path d="M175 0C145 100 225 200 180 300H300C335 200 255 100 310 0Z" fill="#2b4545"/><path d="M139 0C109 100 189 200 144 300M349 0C294 100 374 200 338 300" stroke="#647065" stroke-width="3" fill="none" stroke-dasharray="6 8"/><path d="M95 47H389" stroke="#b2beb1" stroke-width="14"/><text x="242" y="33" text-anchor="middle">다리</text><path d="M350 82h30v9h-30v9h30v9h-30" fill="none" stroke="#d4eb82" stroke-width="3"/><text x="409" y="104" text-anchor="middle" fill="#d4eb82">계단</text><path d="M169 182H329" stroke="#839a95" stroke-width="5" stroke-dasharray="9 9"/><text x="247" y="168" text-anchor="middle" class="map-small">징검다리</text><circle cx="136" cy="229" r="25" fill="#d4eb82"/><text x="136" y="235" text-anchor="middle" fill="#152216">A</text><circle cx="346" cy="229" r="25" fill="#43554a"/><text x="346" y="235" text-anchor="middle">B</text><path d="M134 194v-35m-6 6 6-6 6 6M346 194v-35m-6 6 6-6 6 6" stroke="#d4eb82" stroke-width="2" fill="none"/><text x="136" y="282" text-anchor="middle">A 강변</text><text x="346" y="282" text-anchor="middle">B 강변</text></svg></div><fieldset class="choice-field"><legend>촬영한 강변</legend><div class="two-col">${['A','B'].map(v=>button('bank',`${v} 강변`,'choice '+(bank===v?'selected':''),`data-value="${v}" aria-pressed="${bank===v}"`)).join('')}</div></fieldset><fieldset class="choice-field"><legend>바라본 방향</legend><div class="two-col">${['다리 쪽','반대쪽'].map(v=>button('direction',v,'choice '+(direction===v?'selected':''),`data-value="${v}" aria-pressed="${direction===v}"`)).join('')}</div></fieldset>`;}
function audioCard(r){return `<article class="audio-card"><header><span>${r.position}</span><b>FILE ${r.number}</b></header><div class="audio-controls">${button('speak',icon('play'),'round-play',`data-recording="${r.id}" aria-label="${r.position} 녹취를 기기 음성으로 듣기" aria-pressed="false"`)}<div class="waveform" aria-hidden="true">${Array.from({length:26},(_,i)=>`<i style="height:${8+((i*17+5)%26)}px"></i>`).join('')}</div><span>${r.duration}</span></div><p class="transcript">${esc(r.text)}</p><footer>녹취 · 기기 음성으로 듣기 지원</footer></article>`;}
function stagePuzzle(){let cards=RECORDINGS;if(session&&teamData){const n=teamData.members.length,slot=teamData.me.slot;cards=RECORDINGS.filter((r,i)=>i%n===slot);}
  return `<div class="notebook compact"><span class="note-label">윤서가 기억한 이동</span><p>무대 <span>→</span> 무대 앞 <span>→</span> 객석</p></div>${session?`<p class="team-clue-note">${icon('users')} 각자 받은 녹음의 위치와 파일 숫자를 팀원에게 알려주세요.</p>`:''}<div class="recordings">${cards.map(audioCard).join('')}</div>${session&&cards.length===0?'<p class="empty-note">팀원들이 받은 기록을 모아 순서를 정리해주세요. 당신은 마지막 검증을 맡습니다.</p>':''}`;}
function pathPuzzle(){return `<div class="notebook"><span class="note-label">보관함을 찾는 세 가지 조건</span><ol><li>무대를 떠난 뒤 <strong>되돌아가지 않을 것.</strong></li><li><strong>물을 건너지 않을 것.</strong></li><li>다음 다리를 <strong>지나기 전에 멈출 것.</strong></li></ol></div><div class="path-options">${[{id:'A',title:'강변을 따라 앞으로',desc:'현재 강변 · 다음 다리 직전의 쉼터'},{id:'B',title:'다리를 건너 반대편으로',desc:'반대편 강변 · 도현이 추천한 지점'},{id:'C',title:'왔던 길로 되돌아가기',desc:'출발한 방향 · 지나온 무대 뒤편'}].map(p=>button('path',`<span class="option-letter">${p.id}</span><span><strong>${p.title}</strong><small>${p.desc}</small></span>${pathChoice===p.id?icon('check'):''}`,'path-option '+(pathChoice===p.id?'selected':''),`data-value="${p.id}" aria-pressed="${pathChoice===p.id}"`)).join('')}</div>`;}
function evidenceCard(s,compact=false){return `<article class="evidence-card ${compact?'compact':''}"><header><span>기록 ${s.number}</span><b>${s.time}</b></header>${!compact?`<h3>${s.evidenceTitle}</h3><p>${esc(s.evidence).replaceAll('\n','<br>')}</p>`:''}<footer><span>검증 숫자</span><strong>${s.code}</strong></footer></article>`;}
function finalPuzzle(){return !verifyOpen?`<div class="suspicious-message"><span>윤서의 계정에서 온 요청</span><p>“기록은 삭제해주세요.”</p><small>앞서 확보한 메모와 일치하지 않습니다.</small></div><div class="two-col final-choice">${button('delete-request','기록 삭제','danger-button')}${button('verify','원본 검증','primary')}</div>`:`<div class="notebook"><span class="note-label">마지막 검증</span><p>“그날 일어난 순서로<br>돌려놓아주세요.”</p></div><div class="evidence-grid">${[STAGES[2],STAGES[0],STAGES[3],STAGES[1]].map(s=>evidenceCard(s,true)).join('')}</div>`;}
function answerBox(s){const isPin=s.type==='pin'||s.type==='final';return `<form id="answer-form" class="answer-box"><div class="answer-title">${icon('lock')}<span>${s.number==='05'?'원본 검증':'모바일 자물쇠'}</span>${isPin?'<span class="pin-length">4자리</span>':''}</div>${isPin?`<label for="answer-pin" class="sr-only">네 자리 비밀번호</label><input id="answer-pin" name="answer" class="pin-input" type="text" inputmode="numeric" pattern="[0-9０-９]{4}" maxlength="4" autocomplete="off" spellcheck="false" placeholder="— — — —" value="${esc(pin)}" required aria-describedby="answer-feedback">`:''}<p id="answer-feedback" class="answer-feedback" role="status"></p>${button('submit',`${busy?'확인 중…':s.type==='viewpoint'?'촬영 위치 확인':s.type==='path'?'보관 지점 확인':'자물쇠 열기'} ${icon('unlock')}`,'primary',`type="submit" ${busy?'disabled':''}`)}</form>`;}
function puzzleView(){const s=STAGES[currentStage(state)];return `<div class="section-kicker">기록 ${s.number} / 05<span>${icon('pin')} ${s.place}</span></div><h2 class="page-title">${s.name}</h2><p class="subtitle">${s.instruction}</p><div class="puzzle-surface">${s.id==='bridge'?photoPuzzle():s.id==='bank'?bankPuzzle():s.id==='stage'?stagePuzzle():s.id==='path'?pathPuzzle():finalPuzzle()}</div>${s.type!=='final'||verifyOpen?`<h3 class="puzzle-question">${s.question}</h3>${answerBox(s)}`:''}<div class="puzzle-tools">${button('hint',`${icon('help')} 힌트 ${(state.hints[s.id]||0)}/3`,'text-button')}${button('story',`${icon('message')} 대화 다시 보기`,'text-button')}</div>`;}
function revealView(){const s=STAGES[state.pendingReveal];return `<div class="unlock-header"><span class="unlock-symbol">${icon('unlock')}</span><p class="eyebrow">RECORD ${s.number} · RESTORED</p><h2>잠긴 기록이<br>열렸습니다.</h2></div><div class="messages reveal-messages">${s.reveal.map((m,i)=>message(m,i)).join('')}</div>${s.code?evidenceCard(s):''}<p class="insight">${s.insight}</p>${button('next-stage',`${s.number==='05'?'마지막 메시지 읽기':'다음 기록으로'} ${icon('arrow')}`,'primary')}<p class="footnote">${s.code?'증거함에 자동으로 보관했습니다.':'작품 속 연출이며 실제 외부 기관에 전송하지 않습니다.'}</p>`;}
function evidenceView(){return `<div class="section-kicker">EVIDENCE ARCHIVE<span>${Math.min(state.solved,4)} / 4</span></div><h2 class="page-title">남겨진 증거</h2><p class="subtitle">사라진 11분을 이어줄 조각들.</p>${state.solved===0?`<div class="empty-state">${icon('folder')}<h3>아직 잠긴 기록입니다.</h3><p>첫 자물쇠를 열면<br>윤서가 남긴 증거가 여기에 보관됩니다.</p>${button('tab','첫 기록으로 돌아가기','secondary','data-tab="play"')}</div>`:`<div class="evidence-list">${STAGES.slice(0,Math.min(4,state.solved)).map(s=>evidenceCard(s)).join('')}</div>`}`;}
function logView(){const items=[...INTRO.slice(0,state.reads.intro||0)];STAGES.forEach((s,i)=>{if(i<=state.solved){const shown=state.reads[s.id]||0;if(shown)items.push({from:'system',text:`기록 ${s.number} · ${s.name}`},...s.messages.slice(0,shown));if(i<state.solved)items.push(...s.reveal);}});return `<div class="section-kicker">CONVERSATION LOG<span>읽은 메시지</span></div><h2 class="page-title">다시 읽는 대화</h2><p class="subtitle">처음에는 지나쳤던 말이, 단서가 될 수 있습니다.</p><div class="messages">${items.length?items.map((m,i)=>message(m,i)).join(''):'<div class="empty-state"><p>아직 읽은 메시지가 없습니다.</p></div>'}</div>`;}
function ending(){return `<div class="ending"><div class="ending-image"></div><span class="eyebrow">CASE 001 · CLOSED</span><h2>오늘 여러분은<br>멈춰서<br><em>들어줬어요.</em></h2><div class="ending-copy"><p>윤서는 안전한 곳에서 조사에 협조하고 있습니다.<br>민우에게는 복원된 원본이 전달됐습니다.</p><p>도현의 ‘입력 중’ 표시가 사라집니다.<br>더는 아무 메시지도 오지 않습니다.</p><p>물소리. 발소리. 자전거가 지나가는 소리.<br>처음과 똑같은 양재천입니다.</p></div><div class="completion-stats"><div><strong>5<span> / 5</span></strong><small>복원한 기록</small></div><div><strong>${hintTotal(state)}</strong><small>사용한 힌트</small></div><div><strong>11<span>분</span></strong><small>되찾은 사건 기록</small></div></div>${button('tab',`${icon('folder')} 수집한 증거 돌아보기`,'primary','data-tab="evidence"')}${button('home','첫 화면으로','text-button')}<p class="footnote">〈지워진 11분〉 사전 체험을 마쳤습니다.<br>실제 현장 코스는 답사와 퍼즐 검증 후 공개됩니다.</p></div>`;}
function render(scroll=false){stopVoice();if(screen==='home')app.innerHTML=home();else{let content=tab==='evidence'?evidenceView():tab==='log'?logView():state.pendingReveal!==null?revealView():state.solved===5?ending():introMode?storyView():puzzleOpen?puzzleView():storyView();app.innerHTML=shell(content);}if(scroll){window.scrollTo({top:0,behavior:'instant'});document.querySelector('.game-main')?.scrollTo({top:0});}}
function modal(title,content,cls=''){sheet.innerHTML=`<header class="sheet-header"><h2 id="sheet-title">${title}</h2>${button('close',icon('x'),'icon-button','aria-label="닫기"')}</header><div class="sheet-body ${cls}">${content}</div>`;if(!sheet.open)sheet.showModal();}
function about(){modal('체험 안내',`<p class="lead">당신이 있는 곳이,<br>이야기의 시작점입니다.</p><p>이 버전은 「양재천: 지워진 11분」의 사전 체험판입니다. 모든 단서가 화면에 제공되며, 실제 장소로 이동하지 않아도 끝까지 플레이할 수 있습니다.</p><ul class="plain-list"><li>다섯 자물쇠를 풀어 사건 기록을 복원합니다.</li><li>시간 제한과 오답에 대한 벌점은 없습니다.</li><li>혼자 체험한 진행은 이 브라우저에 저장됩니다. 브라우저 데이터를 삭제하면 초기화됩니다.</li><li>등장인물·사건·촬영 메모·관찰도는 허구입니다.</li></ul><p>실제 현장 코스는 답사 후 별도로 공개됩니다. 사진은 현재 시설 상태나 지정 관찰 지점을 보증하지 않습니다.</p><hr><h3>사진 출처</h3><p class="credit">Yangjaecheon Stream 2016 07<br>Jeon Han / Korea.net / Korean Culture and Information Service<br><a href="https://commons.wikimedia.org/wiki/File:Yangjaecheon_Stream_2016_07.jpg" target="_blank" rel="noopener noreferrer">원본 사진</a> · <a href="https://creativecommons.org/licenses/by-sa/2.0/" target="_blank" rel="noopener noreferrer">CC BY-SA 2.0</a><br>크기 조정 및 화면상 자르기·색상 조정. 사진과 그 변형에는 동일한 라이선스가 적용됩니다.</p>`);}
function settings(){modal('체험 설정',`<div class="setting-row"><div><strong>효과음</strong><p>자물쇠가 열릴 때 짧은 소리가 납니다.</p></div>${button('sound',sound?'켜짐':'꺼짐','toggle-button',`aria-pressed="${sound}"`)}</div><div class="setting-row"><div><strong>진행 저장</strong><p>${session?'팀 진행은 연결된 서버에 저장됩니다.':'이 브라우저에 자동 저장됩니다.'}</p></div>${icon('check')}</div>${session?button('leave-team','팀에서 나가기','secondary full'):button('reset-ask','처음부터 다시 체험','secondary full')}${button('about','체험 안내와 사진 출처','text-button')}`);}
function teamMenu(){if(session){modal('우리 팀',`<p class="micro">초대 코드 · 최대 4명</p><div class="invite-code">${esc(session.code)}</div>${button('copy-code',`${icon('copy')} 초대 코드 복사`,'secondary full')}<div class="member-list">${(teamData?.members||[{name:session.name,slot:0}]).map(m=>`<div><span class="avatar">${m.slot+1}</span><strong>${esc(m.name)}</strong>${m.slot===teamData?.me.slot?'<small>나</small>':''}</div>`).join('')}</div><p class="micro">${connection==='connected'?'팀 진행을 자동으로 동기화하고 있습니다.':'팀의 최신 진행을 확인하고 있습니다.'}</p>${button('resume-team','팀 기록 열기','primary')}`);return;}
  if(!teamConfigured()){modal('함께 체험하기',`<div class="empty-state">${icon('users')}<h3>팀 플레이를 준비하고 있습니다.</h3><p>온라인 연결이 열리면 초대 코드로 모여<br>서로 다른 단서를 나눠 받을 수 있습니다.</p></div>${button('solo-from-team','혼자 먼저 체험하기','primary')}<p class="footnote">혼자 체험할 때는 모든 단서를 확인할 수 있습니다.</p>`);return;}
  modal('함께 체험하기',`<p>초대 코드로 모여 각자의 단서를 나눠보세요.</p><form id="team-form"><label for="nickname">이름 또는 별명</label><input id="nickname" name="nickname" maxlength="12" placeholder="기록을 찾는 사람" required autocomplete="nickname"><label for="invite">초대 코드 <span class="micro">참가할 때만 입력</span></label><input id="invite" name="invite" maxlength="8" placeholder="8자리 초대 코드" autocapitalize="characters" autocomplete="off"><p id="team-error" class="error-text" role="alert"></p><div class="two-col">${button('create-team','팀 만들기','secondary','type="button"')}${button('join-team','팀 참가','primary','type="submit"')}</div></form><p class="micro">최대 4명 · 계정 가입 없이 체험<br>팀 기록과 별명은 생성 후 7일 동안 유지됩니다.</p>`);
}
function begin(){screen='game';tab='play';if(!state.started){state.started=true;state.startedAt=Date.now();state.reads.intro=1;save();}introMode=state.solved===0&&(state.reads.intro||0)<INTRO.length;puzzleOpen=false;render(true);}
function feedback(text){const el=document.querySelector('#answer-feedback');if(el){el.textContent=text;el.classList.add('error');}else toast(text);}
async function submit(){if(busy)return;const idx=currentStage(state),s=STAGES[idx];let answer=s.type==='viewpoint'?bank+direction:s.type==='path'?pathChoice:pin;
  if(s.type==='viewpoint'&&(!bank||!direction))return feedback('강변과 바라본 방향을 모두 선택해주세요.');if(s.type==='path'&&!pathChoice)return feedback('목적지를 선택해주세요.');if(['pin','final'].includes(s.type)&&!/^[0-9０-９]{4}$/.test(pin))return feedback('네 자리 숫자를 입력해주세요.');
  busy=true;const submitBtn=document.querySelector('[data-action="submit"]');if(submitBtn){submitBtn.disabled=true;submitBtn.textContent='기록 확인 중…';}
  try{
    if(session){const result=await teamRequest('submit',{stage:idx,answer},session);if(!result.correct){feedback(result.stale?'팀원이 이미 다음 기록을 열었습니다. 최신 기록을 확인해주세요.':'아직 맞지 않습니다. 단서를 다시 비교해보세요.');if(result.stale)await syncTeam();return;}state={...state,solved:result.team.solved,pendingReveal:idx,attempts:state.attempts+1,finishedAt:result.team.solved===5?Date.now():null};teamData={...teamData,...result};}
    else{const result=submitSolo(state,idx,answer);state=result.state;if(!result.ok){save();feedback(result.reason==='stage'?'현재 기록에서 다시 시도해주세요.':'아직 맞지 않습니다. 단서를 다시 비교해보세요.');return;}}
    save();pin='';tone(true);puzzleOpen=false;render(true);
  }catch(e){feedback(e.message);}finally{busy=false;const btn=document.querySelector('[data-action="submit"]');if(btn){btn.disabled=false;btn.innerHTML=`${s.type==='viewpoint'?'촬영 위치 확인':s.type==='path'?'보관 지점 확인':'자물쇠 열기'} ${icon('unlock')}`;}}
}
async function createOrJoin(action){const name=document.querySelector('#nickname').value.trim(),code=document.querySelector('#invite').value.trim().toUpperCase(),err=document.querySelector('#team-error');if(!name){err.textContent='별명을 입력해주세요.';return;}if(action==='join'&&!/^[A-Z2-9]{8}$/.test(code)){err.textContent='8자리 초대 코드를 확인해주세요.';return;}const buttons=sheet.querySelectorAll('form button');buttons.forEach(b=>b.disabled=true);try{const result=await teamRequest(action,{name,code},null);session={token:result.token,code:result.team.code,name};saveTeam(session);teamData=result;connection='connected';state={...freshState(),started:true,startedAt:Date.now(),solved:result.team.solved,reads:{intro:INTRO.length}};save();sheet.close();introMode=false;puzzleOpen=false;screen='game';tab='play';render(true);schedulePoll();}catch(e){err.textContent=e.message;}finally{buttons.forEach(b=>b.disabled=false);}}
function schedulePoll(){clearTimeout(pollTimer);if(session&&!document.hidden)pollTimer=setTimeout(async()=>{await syncTeam();schedulePoll();},pollDelay);}
async function syncTeam(){if(!session||busy||!teamConfigured())return;try{const data=await teamRequest('state',{},session);teamData=data;connection='connected';pollDelay=5000;if(data.team.solved>state.solved){state={...state,solved:data.team.solved,pendingReveal:data.team.solved-1};save();pin='';puzzleOpen=false;render(true);toast('팀원이 새로운 기록을 열었습니다.');}else{const status=document.querySelector('.status-banner');if(status&&navigator.onLine)status.remove();}}catch(e){connection='error';pollDelay=Math.min(60000,pollDelay*2);if(screen==='game'&&!document.querySelector('.status-banner')){const el=document.createElement('p');el.className='status-banner';el.textContent='팀 연결을 다시 시도하고 있습니다. 현재 단서는 계속 볼 수 있어요.';document.querySelector('.progress-line')?.after(el);}}}
function showHint(){const s=STAGES[currentStage(state)],n=state.hints[s.id]||0;modal('조금만 도움받기',`<p class="micro">기록 ${s.number} · ${s.name}</p><p>필요한 만큼만 열어보세요. 힌트를 사용해도 이야기는 그대로 이어집니다.</p><div class="hint-list">${s.hints.slice(0,n).map((h,i)=>`<article><span>힌트 ${i+1}</span><p>${h}</p></article>`).join('')}</div>${n<3?button('reveal-hint',n===2?'정답에 가까운 마지막 힌트 보기':'다음 힌트 열기','primary'):button('close','단서로 돌아가기','primary')}`);}
function speak(id){if(!('speechSynthesis'in window)){toast('이 브라우저는 음성 읽기를 지원하지 않습니다. 카드의 녹취를 읽어주세요.');return;}if(speakingId===id){stopVoice();return;}stopVoice();const r=RECORDINGS.find(r=>r.id===id);if(!r)return;const voice=new SpeechSynthesisUtterance(r.text.replace(/\[.*?\]/g,''));voice.lang='ko-KR';voice.rate=.87;const ko=window.speechSynthesis.getVoices().find(v=>v.lang.startsWith('ko'));if(ko)voice.voice=ko;speakingId=id;document.querySelector(`[data-recording="${id}"]`)?.classList.add('playing');document.querySelector(`[data-recording="${id}"]`)?.setAttribute('aria-pressed','true');voice.onend=()=>stopVoice();voice.onerror=e=>{stopVoice();if(!['canceled','interrupted'].includes(e.error))toast('음성을 재생하지 못했습니다. 녹취 내용으로 진행할 수 있어요.');};window.speechSynthesis.speak(voice);}
async function act(action,el){
  switch(action){
    case 'start':begin();break;
    case 'home':stopVoice();screen='home';render(true);break;
    case 'tab':tab=el.dataset.tab;render(true);break;
    case 'read-next':{const key=introMode?'intro':STAGES[currentStage(state)].id;const max=introMode?INTRO.length:STAGES[currentStage(state)].messages.length;state.reads[key]=Math.min(max,Math.max(1,state.reads[key]||1)+1);save();tone();render();requestAnimationFrame(()=>document.querySelector('.story-next')?.scrollIntoView({block:'nearest',behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));break;}
    case 'intro-done':introMode=false;state.reads.intro=INTRO.length;save();render(true);break;
    case 'puzzle':puzzleOpen=true;render(true);break;
    case 'story':puzzleOpen=false;render(true);break;
    case 'next-stage':state=advance(state);save();pin='';bank='';direction='';pathChoice='';verifyOpen=false;puzzleOpen=false;introMode=false;render(true);break;
    case 'bank':bank=el.dataset.value;render();break;
    case 'direction':direction=el.dataset.value;render();break;
    case 'path':pathChoice=el.dataset.value;render();break;
    case 'verify':verifyOpen=true;render(true);break;
    case 'delete-request':modal('요청자의 신원을 확인할 수 없습니다.',`<div class="notebook"><span class="note-label">윤서가 미리 남긴 보호 문구</span><p>“이 계정으로 오는 말은<br>나를 증명하지 못해요.”</p></div><p>자료는 삭제되지 않았습니다. 지금까지 모은 원본 기록을 먼저 검증해주세요.</p>${button('verify-close','원본 검증하기','primary')}`);break;
    case 'verify-close':sheet.close();verifyOpen=true;render(true);break;
    case 'hint':showHint();break;
    case 'reveal-hint':state=revealHint(state,STAGES[currentStage(state)].id);save();showHint();render();break;
    case 'original':modal('윤서가 남긴 사진',`<img class="full-photo" src="./assets/yangjaecheon.jpg" alt="양재천 원본 사진"><p class="micro">사전 체험에서는 이 원본과 사진 조각을 비교하세요. 왼쪽부터 숫자를 읽습니다.</p>`);break;
    case 'fragment':modal(`사진 조각 · ${el.dataset.num}`,`<div class="large-fragment" style="background-position:${Number(el.dataset.pos)/3*100}% center"></div><p class="micro">왼쪽부터 몇 번째 자리인지 원본과 비교하세요.</p>`);break;
    case 'close':sheet.close();break;
    case 'about':about();break;
    case 'settings':settings();break;
    case 'sound':sound=!sound;try{localStorage.setItem('yangjae:sound',String(sound));}catch{}tone();render();if(sheet.open&&document.querySelector('#sheet-title').textContent==='체험 설정')settings();toast(sound?'효과음을 켰습니다.':'효과음을 껐습니다.');break;
    case 'reset-ask':modal('처음부터 다시 시작할까요?',`<p>이 기기에 저장된 혼자 체험 기록과 증거를 초기화합니다.</p><div class="two-col">${button('close','계속 체험하기','secondary')}${button('reset','처음부터 시작','danger-button')}</div>`);break;
    case 'reset':state=freshState();save();sheet.close();introMode=false;puzzleOpen=false;pin='';verifyOpen=false;screen='home';render(true);break;
    case 'team-menu':teamMenu();break;
    case 'solo-from-team':sheet.close();begin();break;
    case 'create-team':await createOrJoin('create');break;
    case 'resume-team':sheet.close();await syncTeam();screen='game';tab='play';introMode=false;render(true);schedulePoll();break;
    case 'copy-code':try{await navigator.clipboard.writeText(session.code);toast('초대 코드를 복사했습니다.');}catch{toast(`초대 코드: ${session.code}`);}break;
    case 'leave-team':modal('팀에서 나갈까요?',`<p>팀의 기록은 남아 있지만, 이 기기의 참가 정보는 삭제됩니다. 이후에는 초대 코드로 새로 참가해야 합니다.</p><div class="two-col">${button('close','계속하기','secondary')}${button('confirm-leave','나가기','danger-button')}</div>`);break;
    case 'confirm-leave':clearTeam();session=null;teamData=null;clearTimeout(pollTimer);try{state=restoreState(localStorage.getItem(SAVE_KEY));}catch{state=freshState();}sheet.close();screen='home';render(true);break;
    case 'sync':await syncTeam();render();break;
    case 'speak':speak(el.dataset.recording);break;
  }
}
document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el||el.disabled||el.getAttribute('type')==='submit')return;act(el.dataset.action,el).catch(e=>toast(e.message||'다시 시도해주세요.'));});
document.addEventListener('submit',e=>{if(e.target.id==='answer-form'){e.preventDefault();submit();}if(e.target.id==='team-form'){e.preventDefault();createOrJoin('join');}});
document.addEventListener('input',e=>{if(e.target.id==='answer-pin'){pin=e.target.value.normalize('NFKC').replace(/[^0-9]/g,'').slice(0,4);e.target.value=pin;const f=document.querySelector('#answer-feedback');if(f)f.textContent='';}});
sheet.addEventListener('click',e=>{if(e.target===sheet){const r=sheet.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)sheet.close();}});
document.addEventListener('visibilitychange',()=>{if(document.hidden){stopVoice();clearTimeout(pollTimer);}else{syncTeam();schedulePoll();}});
window.addEventListener('offline',()=>{toast('인터넷 연결이 끊겼습니다.');if(screen==='game')render();});
window.addEventListener('online',()=>{toast('인터넷에 다시 연결됐습니다.');syncTeam();if(screen==='game')render();});
window.addEventListener('pagehide',()=>{stopVoice();clearTimeout(pollTimer);});
render();if(session){syncTeam();schedulePoll();}
if('serviceWorker'in navigator)navigator.serviceWorker.register(new URL('./sw.js',import.meta.url)).catch(()=>{});
const context=document.modelContext;
